<?php
declare(strict_types=1);

namespace App\Support\Holidays;

/**
 * The official holidays of every country and territory, from the
 * python-holidays project (MIT licence, see data/LICENSE-python-holidays),
 * generated by scripts/generate-holiday-dataset.py into data/<CC>.json for
 * the years the files declare (2010-2060).
 *
 * The countries with a hand-written rule table (HolidayRules) are read from
 * that table, which works for any year; every other country comes from here,
 * with the same selection, preview and closure machinery. Dates that depend
 * on the sighting of the moon are marked as estimated in the data.
 *
 * Date strings: "d|MMDD:2010-2060,2063|…" (by day of the year) or
 * "y|2026:0319-0324,1225|…" (by year, with runs of days).
 */
final class HolidayDataset
{
    /** @var array<string, array<string, mixed>|false> */
    private static array $files = [];

    /** @var array<string, array<int, list<string>>> decoded date strings */
    private static array $decoded = [];

    private static function dir(): string
    {
        return __DIR__ . '/data';
    }

    /** @return list<string> country codes with a data file */
    public static function codes(): array
    {
        static $codes = null;
        if ($codes === null) {
            $codes = [];
            foreach (glob(self::dir() . '/*.json') ?: [] as $file) {
                $code = basename($file, '.json');
                if (preg_match('/^[A-Z]{2}$/', $code) === 1) {
                    $codes[] = $code;
                }
            }
            sort($codes);
        }
        return $codes;
    }

    /** @return array<string, mixed>|null the decoded file of $code */
    private static function file(string $code): ?array
    {
        $code = strtoupper($code);
        if (preg_match('/^[A-Z]{2}$/', $code) !== 1) {
            return null;
        }
        if (!array_key_exists($code, self::$files)) {
            $path = self::dir() . '/' . $code . '.json';
            $data = is_file($path) ? json_decode((string) file_get_contents($path), true) : null;
            self::$files[$code] = is_array($data) ? $data : false;
        }
        return self::$files[$code] === false ? null : self::$files[$code];
    }

    /** @return array{int, int}|null first and last year of the data */
    public static function years(string $code): ?array
    {
        $years = self::file($code)['years'] ?? null;
        return is_array($years) && count($years) === 2 ? [(int) $years[0], (int) $years[1]] : null;
    }

    /**
     * The country in the shape of HolidayRules::countries(): the regions
     * are its subdivisions, each holiday one rule. A rule reads its dates
     * through ['dataset', code, id, region].
     *
     * @return array{name: string, regions?: array<string, string>, rules: list<array<string, mixed>>, dataset: true}|null
     */
    public static function country(string $code, string $region = ''): ?array
    {
        $data = self::file($code);
        if ($data === null) {
            return null;
        }
        $code = strtoupper($code);
        $rules = [];
        foreach ((array) ($data['holidays'] ?? []) as $holiday) {
            if (!is_array($holiday) || !isset($holiday['id'], $holiday['name'])) {
                continue;
            }
            $rule = [
                'id' => (string) $holiday['id'],
                'name' => (string) $holiday['name'],
                'name_en' => (string) ($holiday['en'] ?? $holiday['name']),
                'rule' => ['dataset', $code, (string) $holiday['id'], $region],
                'category' => (string) ($holiday['category'] ?? 'public'),
            ];
            if (($holiday['category'] ?? 'public') !== 'public') {
                $rule['optional'] = true;
            }
            if (!isset($holiday['dates']) && is_array($holiday['regional'] ?? null)) {
                $rule['regions'] = array_map('strval', array_keys($holiday['regional']));
            }
            $rules[] = $rule;
        }
        $out = ['name' => $code, 'rules' => $rules, 'dataset' => true];
        $subdivisions = is_array($data['subdivisions'] ?? null) ? $data['subdivisions'] : [];
        if ($subdivisions !== []) {
            $out['regions'] = array_map('strval', $subdivisions);
        }
        return $out;
    }

    /** Badge of a holiday category other than "public", in the interface language. */
    public static function categoryLabel(string $category): string
    {
        return match ($category) {
            'optional' => __('facoltativa'),
            'optional_women' => __('facoltativa per le donne'),
            'government' => __('uffici pubblici'),
            'unofficial' => __('non ufficiale'),
            'bank' => __('banche'),
            'half_day' => __('mezza giornata'),
            'school' => __('scuole'),
            'de_facto' => __('di fatto'),
            'armed_forces' => __('forze armate'),
            'catholic' => __('comunità cattolica'),
            'orthodox' => __('comunità ortodossa'),
            'christian' => __('comunità cristiana'),
            'hebrew' => __('comunità ebraica'),
            'islamic' => __('comunità musulmana'),
            'hindu' => __('comunità induista'),
            'sabian' => __('comunità mandea'),
            'yazidi' => __('comunità yazida'),
            'serbian' => __('comunità serba'),
            'roma' => __('comunità rom'),
            'vlach' => __('comunità valacca'),
            'bosnian' => __('comunità bosgnacca'),
            'albanian' => __('comunità albanese'),
            'turkish' => __('comunità turca'),
            'armenian' => __('comunità armena'),
            default => $category,
        };
    }

    /** The holiday $id of $code, raw. @return array<string, mixed>|null */
    private static function holiday(string $code, string $id): ?array
    {
        foreach ((array) (self::file($code)['holidays'] ?? []) as $holiday) {
            if (is_array($holiday) && ($holiday['id'] ?? null) === $id) {
                return $holiday;
            }
        }
        return null;
    }

    /**
     * The dates of holiday $id in $year (national, plus those of $region).
     * None outside the years of the file (years()): that day counts as open.
     *
     * @return list<string>
     */
    public static function dates(string $code, string $id, int $year, string $region = ''): array
    {
        $holiday = self::holiday($code, $id);
        if ($holiday === null) {
            return [];
        }
        $dates = isset($holiday['dates']) ? self::decode((string) $holiday['dates'])[$year] ?? [] : [];
        if ($region !== '' && isset($holiday['regional'][$region])) {
            $dates = array_merge($dates, self::decode((string) $holiday['regional'][$region])[$year] ?? []);
        }
        $dates = array_values(array_unique($dates));
        sort($dates);
        return $dates;
    }

    /** True when a date of holiday $id in $year is an estimate (lunar sighting). */
    public static function isEstimated(string $code, string $id, int $year): bool
    {
        $holiday = self::holiday($code, $id);
        return $holiday !== null && isset($holiday['estimated'])
            && (self::decode((string) $holiday['estimated'])[$year] ?? []) !== [];
    }

    /**
     * @return array<int, list<string>> year => Y-m-d dates
     */
    public static function decode(string $encoded): array
    {
        if (isset(self::$decoded[$encoded])) {
            return self::$decoded[$encoded];
        }
        $out = [];
        $form = substr($encoded, 0, 2);
        foreach (explode('|', substr($encoded, 2)) as $part) {
            [$head, $tail] = array_pad(explode(':', $part, 2), 2, '');
            if ($form === 'd|') {
                foreach (explode(',', $tail) as $run) {
                    [$from, $to] = array_pad(explode('-', $run, 2), 2, null);
                    for ($y = (int) $from; $y <= (int) ($to ?? $from); $y++) {
                        $date = sprintf('%04d-%s-%s', $y, substr($head, 0, 2), substr($head, 2, 2));
                        if (checkdate((int) substr($head, 0, 2), (int) substr($head, 2, 2), $y)) {
                            $out[$y][] = $date;
                        }
                    }
                }
            } elseif ($form === 'y|') {
                $y = (int) $head;
                foreach (explode(',', $tail) as $run) {
                    [$from, $to] = array_pad(explode('-', $run, 2), 2, null);
                    $day = new \DateTimeImmutable(sprintf('%04d-%s-%s', $y, substr($from, 0, 2), substr($from, 2, 2)), new \DateTimeZone('UTC'));
                    $last = $to === null ? $day : new \DateTimeImmutable(sprintf('%04d-%s-%s', $y, substr($to, 0, 2), substr($to, 2, 2)), new \DateTimeZone('UTC'));
                    for (; $day <= $last; $day = $day->modify('+1 day')) {
                        $out[$y][] = $day->format('Y-m-d');
                    }
                }
            }
        }
        foreach ($out as &$dates) {
            sort($dates);
        }
        unset($dates);
        return self::$decoded[$encoded] = $out;
    }
}
